#include <vector>
#include <unordered_set>
using namespace std;

class Solution {
public:
    long long findSmallestMissingMultiple(vector<int>& nums, int k) {
        unordered_set<long long> present(nums.begin(), nums.end());
        long long candidate = k;
        while (present.count(candidate)) {
            candidate += k;
        }
        return candidate;
    }
};

import java.util.*;

class Solution {
    public long findSmallestMissingMultiple(int[] nums, int k) {
        Set<Long> present = new HashSet<>();
        for (int x : nums) present.add((long)x);
        long candidate = k;
        while (present.contains(candidate)) {
            candidate += k;
        }
        return candidate;
    }
}

var findSmallestMissingMultiple = function(nums, k) {
    const present = new Set(nums.map(x => BigInt(x)));
    let candidate = BigInt(k);
    const step = BigInt(k);
    while (present.has(candidate)) {
        candidate += step;
    }
    return Number(candidate);
};
